exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  02 · kept and same                                          ★★☆ core
//  concepts: Intersect · SequenceEqual
// ─────────────────────────────────────────────────────────────────────────
//
//  Before writing anything, a good endpoint asks: did this payload change
//  the collection at all? Order may or may not matter — decide which.

using static Bootcamp.Check;

List<string> Kept(List<string> current, List<string> incoming)
{
    return incoming.Intersect(current).ToList();
}

bool SameList(List<string> a, List<string> b)
{
    return a.SequenceEqual(b);
}

bool SameItemsAnyOrder(List<string> a, List<string> b)
{
    return !a.Except(b).Any() && !b.Except(a).Any();
}

exercises.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("Kept([a,b], [b,c]) -> [b]", () =>
    Eq(Kept(["a", "b"], ["b", "c"]), new[] { "b" }));

Test("Kept([], [x]) -> [] (boundary)", () =>
    Eq(Kept([], ["x"]), Array.Empty<string>()));

Test("SameList([a,b], [a,b]) -> true", () =>
    Eq(SameList(["a", "b"], ["a", "b"]), true));

Test("SameList([a,b], [b,a]) -> false (order matters)", () =>
    Eq(SameList(["a", "b"], ["b", "a"]), false));

Test("SameItemsAnyOrder([a,b], [b,a]) -> true", () =>
    Eq(SameItemsAnyOrder(["a", "b"], ["b", "a"]), true));

Test("SameItemsAnyOrder([a], [a,a]) -> true (boundary: set semantics ignore duplicates)", () =>
    Eq(SameItemsAnyOrder(["a"], ["a", "a"]), true));

