exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  04 · batch membership                                       ★☆☆ warm-up
//  concepts: ToHashSet · lookup cost
// ─────────────────────────────────────────────────────────────────────────
//
//  A bulk endpoint receives requested ids and must report which exist.
//  Scanning the existing list once per id is O(n·m) — build a set once.

using static Bootcamp.Check;

List<int> MissingIds(List<int> requested, List<int> existing)
{
    var have = existing.ToHashSet();
    return requested.Distinct().Where(id => !have.Contains(id)).ToList();
}

List<int> KnownIds(List<int> requested, List<int> existing)
{
    var have = existing.ToHashSet();
    return requested.Distinct().Where(id => have.Contains(id)).ToList();
}

