using static Bootcamp.Check;

List<string> Labels(List<string> names, List<int> qty)
{
    return names.Zip(qty, (n, q) => $"{n} x{q}").ToList();
}

int PairedCount(List<string> names, List<int> qty)
{
    return Math.Min(names.Count, qty.Count);
