exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  08 · version reconcile                                      ★★☆ core
//  concepts: keyed diff · cache sync
// ─────────────────────────────────────────────────────────────────────────
//
//  A mobile client caches (Id, Version) pairs. On sync the server says
//  what it holds; the client must refresh stale ids and fetch new ones.

using static Bootcamp.Check;

List<int> ToRefresh(List<(int Id, int Ver)> client, List<(int Id, int Ver)> server)
{
    var clientVer = client.ToDictionary(c => c.Id, c => c.Ver);   // one O(m) pass, then O(1) probes
    return server
        .Where(s => clientVer.TryGetValue(s.Id, out var ver) && ver < s.Ver)
        .Select(s => s.Id)
        .ToList();
}

List<int> NewOnServer(List<(int Id, int Ver)> client, List<(int Id, int Ver)> server)
{
    return server.ExceptBy(client.Select(c => c.Id), s => s.Id).Select(s => s.Id).ToList();
}

exercises.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("client (1,1)(2,3)(3,2) vs server (1,2)(2,3)(4,1): refresh [1]", () =>
    Eq(ToRefresh([(1, 1), (2, 3), (3, 2)], [(1, 2), (2, 3), (4, 1)]), new[] { 1 }));

Test("client (1,1)(2,3)(3,2) vs server (1,2)(2,3)(4,1): new [4]", () =>
    Eq(NewOnServer([(1, 1), (2, 3), (3, 2)], [(1, 2), (2, 3), (4, 1)]), new[] { 4 }));

Test("equal versions refresh nothing (boundary)", () =>
    Eq(ToRefresh([(2, 3)], [(2, 3)]), Array.Empty<int>()));

Test("an empty client has nothing to refresh (boundary)", () =>
    Eq(ToRefresh([], [(1, 2), (4, 1)]), Array.Empty<int>()));

Test("an empty client gets every server id as new (boundary)", () =>
    Eq(NewOnServer([], [(1, 2), (4, 1)]), new[] { 1, 4 }));

Test("a client copy NEWER than the server is not refreshed (boundary: strictly higher only)", () =>
    Eq(ToRefresh([(5, 4)], [(5, 3)]), Array.Empty<int>()));
